-- koloni-148: kovan içi ses protokolü (KİLİTLİ 2026-10-14)
on conflict (id) do update set ad_tr = excluded.ad_tr, ad_en = excluded.ad_en, hz_min = excluded.hz_min, hz_max = excluded.hz_max, yapi = excluded.yapi, anlam = excluded.anlam, seviye = excluded.seviye, kaynak = excluded.kaynak, kaynak_zayif = excluded.kaynak_zayif, sira = excluded.sira, updated_at = now();
-- k148 KİLİTLİ 2026-10-14: erkek arı sınıfı kaldırıldı (150–200 Hz = yelpazeleme); eski 'isci_vizilti' ve 'ogul_oncesi' yerine taban_* / ogul_egilim
update public.ses_olaylari set sinif = 'yelpazeleme' where sinif = 'erkek_ucusu';
update public.ses_olaylari set sinif = 'taban_gunduz' where sinif = 'isci_vizilti';
update public.ses_olaylari set sinif = 'ogul_egilim' where sinif = 'ogul_oncesi';
delete from public.ses_siniflari where id in ('erkek_ucusu', 'isci_vizilti', 'ogul_oncesi');
